insert into public.patient_summaries (patient_id, week_start, text, model, source, created_at) values
  ('p-james', current_date - 5, 'James''s symmetry has stayed between 52% and 54% across 9 sessions in the last 14 days, and the last session was 4 days ago. Watch data shows weak-arm active time falling from 95 to 58 minutes a day over the last 20 days, with the use ratio down from 0.55 to 0.38.', 'pregenerated', 'pregenerated', least(current_date + time '10:00:00', now())),
  ('p-maria', current_date - 5, 'Maria''s symmetry rose from 45% to 71% across 19 sessions in the last 20 days, with compensation steady at about 12% of weak-arm reps. The last 3 sessions averaged 69%, above the phase 2 target of 65%, and resting heart rate held at 68 bpm.', 'pregenerated', 'pregenerated', least(current_date + time '10:00:00', now())),
  ('p-priya', current_date - 5, 'Priya''s symmetry rose from 40% to 57%, but about 55% of weak-arm reps in the last 3 sessions involved leaning or shoulder hiking. Resting heart rate climbed from 66 to 80 bpm over the past week, and the latest systolic reading of 148 mmHg is above the limit of 140.', 'pregenerated', 'pregenerated', least(current_date + time '10:00:00', now()));
